/**
 * @fileoverview Test the usage of a deprecated Class
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const rule = require('../../../lib/rules/no-deprecated-class-usage'),
    RuleTester = require('eslint').RuleTester;

// ------------------------------------------------------------------------------
// Tests
// ------------------------------------------------------------------------------

const ruleTester = new RuleTester({
    settings: {
        extjs: {
            toolkit: 'modern',
            fromVersion: '6.0', 
            toVersion: '7.9.0'
        }
    }
});

ruleTester.run('no-deprecated-class-usage', rule, {

    valid: [
        {
            code: `
                var MyCustomClass = Ext.extend(Ext.chart.AbstractChart, {
                    customProp: true
                });
            `
        }
    ],

    invalid: [
        {
            code: `
                var MyCustomClass = Ext.extend(Ext.AbstractManager, {
                    customProp: true
                });
                var MyCustomDataClass = Ext.extend(true ? Ext.data.Types : Ext.data.Error, {
                    customProp: true
                });
                Ext.define('MyCustomPlugin', {
                    extend: 'Ext.plugin.Responsive'
                });
            `,
            errors: [
                { message: /Usage of deprecated Class 'Ext.AbstractManager' found.*/ },
                { message: /Usage of deprecated Class 'Ext.data.Types' found.*/ },
                { message: /Usage of deprecated Class 'Ext.data.Error' found.*/ },
                { message: /Usage of deprecated Class 'Ext.plugin.Responsive' found.*/ }
            ]
        },
        {
            code: `
                Ext.define('Ext4App.view.Container', {
                    extend: 'Ext.Container',
                    xtype: 'app-container',
                    someMethod: function () {
                        Ext.create({xclass: 'Ext.util.Draggable'});
                        Ext.create({xclass: 'Ext.plugin.Responsive'});

                        Ext.create('Ext.util.Draggable', {});
                        Ext.create('Ext.plugin.Responsive', {});

                        new Ext.util.Draggable({});
                        new Ext.plugin.Responsive({});
                    }
                });
                Ext.define('MyCustomDraggable', {
                    extend: 'Ext.util.Draggable'
                });
                Ext.define('overrides.Draggable', {
                    override: 'Ext.util.Draggable'
                });
                var MyCustomDraggable = Ext.extend(Ext.util.Draggable, {});
                Ext.util.Draggable.prototype.customMethod = function () {};
            `,
            errors: 10
        }
    ]
});
